//! 表达式词法分析与语法解析
//!
//! 表达式语法 (覆盖 WebGAL 的 `setVar:var=expr` 与 `-when=expr` 常用子集):
//!
//! - 字面量: 数字 (`1`, `1.5`, `.5`, `1e3`), 字符串 (`'...'` / `"..."`, 含转义), `true` / `false`
//! - 标识符: `[a-zA-Z_][a-zA-Z0-9_]*`, 用作变量引用或函数名
//! - 裸词: 不是合法标识符的“词”(如 `人物名称`) 回退为字符串字面量
//! - 一元: `!` `-` `+`; 二元: `+ - * / %`, `== != < > <= >=`, `&& ||`; 三元: `cond ? a : b`
//! - 括号与函数调用: `f(a, b)`
//!
//! 刻意不支持 (作为规范): 赋值, 成员访问, `$` 内置变量域, 数组 / 对象字面量,
//! `===` / `!==`, 位运算, 过滤器.

use std::{fmt, str::FromStr};

use crate::{
    error::{EvaluationError, ParseError, ParseErrorKind},
    evaluate::{EmptyEvaluationContext, EvaluationContext, evaluate_ast},
    value::{Number, Value, ValueKind},
};

// -------- 词法分析 --------

/// 词法记号
#[derive(Debug, Clone, PartialEq)]
struct Token {
    kind: TokenKind,
    offset: usize,
}

#[derive(Debug, Clone, PartialEq)]
enum TokenKind {
    Number(Number),
    Str(String),
    Bool(bool),
    Var(String),
    // 运算符
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    EqEq,
    NotEq,
    Lt,
    Gt,
    LtEq,
    GtEq,
    AndAnd,
    OrOr,
    Bang,
    // 其他符号
    Question,
    Colon,
    Comma,
    LParen,
    RParen,
}

/// 词字符: 空白与运算符 / 标点 / 引号之外的字符都属于“词”的一部分
fn is_word_char(character: char) -> bool {
    !character.is_whitespace()
        && !matches!(
            character,
            '+' | '-'
                | '*'
                | '/'
                | '%'
                | '('
                | ')'
                | '<'
                | '>'
                | '='
                | '!'
                | '&'
                | '|'
                | '?'
                | ':'
                | ','
                | ';'
                | '.'
                | '\''
                | '"'
                | '$'
        )
}

fn is_identifier(word: &str) -> bool {
    let mut characters = word.chars();
    match characters.next() {
        Some(character) if character.is_ascii_alphabetic() || character == '_' => {}
        _ => return false,
    }
    characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
}

struct Lexer<'a> {
    source: &'a str,
    position: usize,
}

impl<'a> Lexer<'a> {
    fn new(source: &'a str) -> Self {
        Self {
            source,
            position: 0,
        }
    }

    /// 当前字符 (字节偏移已对齐字符边界)
    fn peek(&self) -> Option<char> {
        self.source[self.position..].chars().next()
    }

    /// 当前位置之后的第二个字符
    fn peek_second(&self) -> Option<char> {
        let mut characters = self.source[self.position..].chars();
        characters.next();
        characters.next()
    }

    fn bump(&mut self) -> Option<char> {
        let character = self.peek()?;
        self.position += character.len_utf8();
        Some(character)
    }

    fn consume_digits(&mut self) {
        while self
            .peek()
            .is_some_and(|character| character.is_ascii_digit())
        {
            self.bump();
        }
    }

    fn lex_all(mut self) -> Result<Vec<Token>, ParseError> {
        let mut tokens = Vec::new();
        while let Some(character) = self.peek() {
            if character.is_whitespace() {
                self.bump();
                continue;
            }
            let offset = self.position;
            let kind = match character {
                '+' => {
                    self.bump();
                    TokenKind::Plus
                }
                '-' => {
                    self.bump();
                    TokenKind::Minus
                }
                '*' => {
                    self.bump();
                    TokenKind::Star
                }
                '/' => {
                    self.bump();
                    TokenKind::Slash
                }
                '%' => {
                    self.bump();
                    TokenKind::Percent
                }
                '(' => {
                    self.bump();
                    TokenKind::LParen
                }
                ')' => {
                    self.bump();
                    TokenKind::RParen
                }
                '?' => {
                    self.bump();
                    TokenKind::Question
                }
                ':' => {
                    self.bump();
                    TokenKind::Colon
                }
                ',' => {
                    self.bump();
                    TokenKind::Comma
                }
                '=' => {
                    self.bump();
                    match self.peek() {
                        Some('=') => {
                            self.bump();
                            if self.peek() == Some('=') {
                                return Err(ParseError::new(
                                    ParseErrorKind::UnsupportedOperator,
                                    offset,
                                    "不支持 `===` 运算符, 请使用 `==`",
                                ));
                            }
                            TokenKind::EqEq
                        }
                        _ => {
                            return Err(ParseError::new(
                                ParseErrorKind::UnsupportedOperator,
                                offset,
                                "赋值运算符 `=` 不能出现在表达式中, 条件判断请使用 `==`",
                            ));
                        }
                    }
                }
                '!' => {
                    self.bump();
                    if self.peek() == Some('=') {
                        self.bump();
                        if self.peek() == Some('=') {
                            return Err(ParseError::new(
                                ParseErrorKind::UnsupportedOperator,
                                offset,
                                "不支持 `!==` 运算符, 请使用 `!=`",
                            ));
                        }
                        TokenKind::NotEq
                    } else {
                        TokenKind::Bang
                    }
                }
                '<' => {
                    self.bump();
                    if self.peek() == Some('=') {
                        self.bump();
                        TokenKind::LtEq
                    } else {
                        TokenKind::Lt
                    }
                }
                '>' => {
                    self.bump();
                    if self.peek() == Some('=') {
                        self.bump();
                        TokenKind::GtEq
                    } else {
                        TokenKind::Gt
                    }
                }
                '&' => {
                    self.bump();
                    if self.peek() == Some('&') {
                        self.bump();
                        TokenKind::AndAnd
                    } else {
                        return Err(ParseError::new(
                            ParseErrorKind::UnsupportedOperator,
                            offset,
                            "不支持按位与 `&`, 逻辑与请使用 `&&`",
                        ));
                    }
                }
                '|' => {
                    self.bump();
                    if self.peek() == Some('|') {
                        self.bump();
                        TokenKind::OrOr
                    } else {
                        return Err(ParseError::new(
                            ParseErrorKind::UnsupportedOperator,
                            offset,
                            "不支持按位或 `|`, 逻辑或请使用 `||`",
                        ));
                    }
                }
                '$' => {
                    return Err(ParseError::new(
                        ParseErrorKind::UnsupportedOperator,
                        offset,
                        "不支持 `$` 内置变量域访问, 请使用普通变量名",
                    ));
                }
                '\'' | '"' => self.lex_string(character)?,
                '0'..='9' => self.lex_number()?,
                '.' if self
                    .peek_second()
                    .is_some_and(|character| character.is_ascii_digit()) =>
                {
                    self.lex_number()?
                }
                _ if is_word_char(character) => self.lex_word(),
                _ => {
                    return Err(ParseError::new(
                        ParseErrorKind::UnexpectedCharacter,
                        offset,
                        format!("无法识别的字符 `{character}`"),
                    ));
                }
            };
            tokens.push(Token { kind, offset });
        }
        Ok(tokens)
    }

    fn lex_number(&mut self) -> Result<TokenKind, ParseError> {
        let start = self.position;
        if self.peek() == Some('.') {
            self.bump();
            self.consume_digits();
        } else {
            self.consume_digits();
            if self.peek() == Some('.') {
                self.bump();
                self.consume_digits();
            }
        }
        // 指数部分
        if matches!(self.peek(), Some('e' | 'E')) {
            self.bump();
            if matches!(self.peek(), Some('+' | '-')) {
                self.bump();
            }
            let exponent_start = self.position;
            self.consume_digits();
            if self.position == exponent_start {
                return Err(ParseError::new(
                    ParseErrorKind::InvalidNumber,
                    start,
                    "数字格式错误: 指数部分缺少数字",
                ));
            }
        }
        // 数字后不允许直接跟其他词字符 (如 `1x`, `1e3a`, `0x10`)
        if self.peek().is_some_and(is_word_char) {
            return Err(ParseError::new(
                ParseErrorKind::InvalidNumber,
                start,
                "数字字面量后不能直接跟其他字符",
            ));
        }
        let text = &self.source[start..self.position];
        // 无小数点与指数的整数字面量保持整数表示
        if !text.contains(['.', 'e', 'E'])
            && let Ok(integer) = text.parse::<i64>()
        {
            return Ok(TokenKind::Number(Number::Integer(integer)));
        }
        // 超出 i64 范围 (如 99999999999999999999999) 时回退浮点数
        let value = text.parse::<f64>().map_err(|_| {
            ParseError::new(
                ParseErrorKind::InvalidNumber,
                start,
                format!("数字格式错误: `{text}`"),
            )
        })?;
        match Number::from_f64(value) {
            Some(number) => Ok(TokenKind::Number(number)),
            None => Err(ParseError::new(
                ParseErrorKind::InvalidNumber,
                start,
                "数字超出可表示范围",
            )),
        }
    }

    fn lex_string(&mut self, quote: char) -> Result<TokenKind, ParseError> {
        let start = self.position;
        self.bump(); // 开引号
        let mut value = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(ParseError::new(
                        ParseErrorKind::UnclosedString,
                        start,
                        "字符串未闭合",
                    ));
                }
                Some(character) if character == quote => {
                    self.bump();
                    return Ok(TokenKind::Str(value));
                }
                Some('\\') => {
                    self.bump();
                    match self.bump() {
                        Some('n') => value.push('\n'),
                        Some('t') => value.push('\t'),
                        Some('r') => value.push('\r'),
                        Some('\\') => value.push('\\'),
                        Some('\'') => value.push('\''),
                        Some('"') => value.push('"'),
                        Some(other) => {
                            return Err(ParseError::new(
                                ParseErrorKind::InvalidEscape,
                                self.position - other.len_utf8(),
                                format!("无效的转义 `\\{other}`"),
                            ));
                        }
                        None => {
                            return Err(ParseError::new(
                                ParseErrorKind::UnclosedString,
                                start,
                                "字符串未闭合",
                            ));
                        }
                    }
                }
                Some(character) => {
                    value.push(character);
                    self.bump();
                }
            }
        }
    }

    fn lex_word(&mut self) -> TokenKind {
        let start = self.position;
        while self.peek().is_some_and(is_word_char) {
            self.bump();
        }
        let word = &self.source[start..self.position];
        match word {
            "true" => TokenKind::Bool(true),
            "false" => TokenKind::Bool(false),
            _ if is_identifier(word) => TokenKind::Var(word.to_string()),
            // 裸词回退为字符串字面量, 与 WebGAL 的 `setVar:a=人物名称` 行为一致
            _ => TokenKind::Str(word.to_string()),
        }
    }
}

// -------- 语法树 --------

/// 一元运算符
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum UnOp {
    Neg,
    Pos,
    Not,
}

/// 二元运算符
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Eq,
    Ne,
    Lt,
    Gt,
    LtEq,
    GtEq,
}

/// 逻辑运算符 (短路求值)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum LogicOp {
    And,
    Or,
}

/// 表达式语法树
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Expr {
    Number(Number),
    Bool(bool),
    Str(String),
    Var(String),
    Unary(UnOp, Box<Expr>),
    Binary(BinOp, Box<Expr>, Box<Expr>),
    Logical(LogicOp, Box<Expr>, Box<Expr>),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>),
    Call(String, Vec<Expr>),
}

// -------- 解析器 --------

/// 解析与求值的最大嵌套深度, 防止恶意输入导致栈溢出
const MAX_DEPTH: usize = 128;

struct Parser<'a> {
    source: &'a str,
    tokens: Vec<Token>,
    position: usize,
    depth: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.position)
    }

    fn bump(&mut self) -> Option<Token> {
        let token = self.tokens.get(self.position).cloned();
        if token.is_some() {
            self.position += 1;
        }
        token
    }

    fn guard(&mut self) -> Result<(), ParseError> {
        self.depth += 1;
        if self.depth > MAX_DEPTH {
            Err(ParseError::new(
                ParseErrorKind::NestingTooDeep,
                0,
                "表达式嵌套过深",
            ))
        } else {
            Ok(())
        }
    }

    fn unexpected(&self, message: &str) -> ParseError {
        match self.peek() {
            Some(token) => {
                ParseError::new(ParseErrorKind::UnexpectedCharacter, token.offset, message)
            }
            None => ParseError::new(ParseErrorKind::UnexpectedEnd, self.source.len(), message),
        }
    }

    fn parse_expression(&mut self) -> Result<Expr, ParseError> {
        self.parse_ternary()
    }

    fn parse_ternary(&mut self) -> Result<Expr, ParseError> {
        let condition = self.parse_or()?;
        if self
            .peek()
            .is_some_and(|token| token.kind == TokenKind::Question)
        {
            self.bump();
            let then_branch = self.parse_expression()?;
            if !self
                .peek()
                .is_some_and(|token| token.kind == TokenKind::Colon)
            {
                return Err(self.unexpected("缺少 `:`"));
            }
            self.bump();
            let else_branch = self.parse_expression()?;
            Ok(Expr::Ternary(
                Box::new(condition),
                Box::new(then_branch),
                Box::new(else_branch),
            ))
        } else {
            Ok(condition)
        }
    }

    fn parse_or(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_and()?;
        while self
            .peek()
            .is_some_and(|token| token.kind == TokenKind::OrOr)
        {
            self.bump();
            let rhs = self.parse_and()?;
            lhs = Expr::Logical(LogicOp::Or, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_and(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_equality()?;
        while self
            .peek()
            .is_some_and(|token| token.kind == TokenKind::AndAnd)
        {
            self.bump();
            let rhs = self.parse_equality()?;
            lhs = Expr::Logical(LogicOp::And, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_equality(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_ordering()?;
        loop {
            let operator = match self.peek().map(|token| &token.kind) {
                Some(TokenKind::EqEq) => BinOp::Eq,
                Some(TokenKind::NotEq) => BinOp::Ne,
                _ => break,
            };
            self.bump();
            let rhs = self.parse_ordering()?;
            lhs = Expr::Binary(operator, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_ordering(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_additive()?;
        loop {
            let operator = match self.peek().map(|token| &token.kind) {
                Some(TokenKind::Lt) => BinOp::Lt,
                Some(TokenKind::Gt) => BinOp::Gt,
                Some(TokenKind::LtEq) => BinOp::LtEq,
                Some(TokenKind::GtEq) => BinOp::GtEq,
                _ => break,
            };
            self.bump();
            let rhs = self.parse_additive()?;
            lhs = Expr::Binary(operator, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_additive(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_multiplicative()?;
        loop {
            let operator = match self.peek().map(|token| &token.kind) {
                Some(TokenKind::Plus) => BinOp::Add,
                Some(TokenKind::Minus) => BinOp::Sub,
                _ => break,
            };
            self.bump();
            let rhs = self.parse_multiplicative()?;
            lhs = Expr::Binary(operator, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_unary()?;
        loop {
            let operator = match self.peek().map(|token| &token.kind) {
                Some(TokenKind::Star) => BinOp::Mul,
                Some(TokenKind::Slash) => BinOp::Div,
                Some(TokenKind::Percent) => BinOp::Rem,
                _ => break,
            };
            self.bump();
            let rhs = self.parse_unary()?;
            lhs = Expr::Binary(operator, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_unary(&mut self) -> Result<Expr, ParseError> {
        self.guard()?;
        match self.peek().map(|token| &token.kind) {
            Some(TokenKind::Bang) => {
                self.bump();
                Ok(Expr::Unary(UnOp::Not, Box::new(self.parse_unary()?)))
            }
            Some(TokenKind::Minus) => {
                self.bump();
                Ok(Expr::Unary(UnOp::Neg, Box::new(self.parse_unary()?)))
            }
            Some(TokenKind::Plus) => {
                self.bump();
                Ok(Expr::Unary(UnOp::Pos, Box::new(self.parse_unary()?)))
            }
            _ => self.parse_primary(),
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        let token = self.bump().ok_or_else(|| {
            ParseError::new(
                ParseErrorKind::UnexpectedEnd,
                self.source.len(),
                "表达式不完整",
            )
        })?;
        match token.kind {
            TokenKind::Number(number) => Ok(Expr::Number(number)),
            TokenKind::Str(string) => Ok(Expr::Str(string)),
            TokenKind::Bool(boolean) => Ok(Expr::Bool(boolean)),
            TokenKind::Var(name) => {
                if self
                    .peek()
                    .is_some_and(|token| token.kind == TokenKind::LParen)
                {
                    self.bump();
                    self.parse_arguments(name)
                } else {
                    Ok(Expr::Var(name))
                }
            }
            TokenKind::LParen => {
                if self
                    .peek()
                    .is_some_and(|token| token.kind == TokenKind::RParen)
                {
                    return Err(ParseError::new(
                        ParseErrorKind::UnexpectedCharacter,
                        token.offset,
                        "括号内不能为空",
                    ));
                }
                self.guard()?;
                let inner = self.parse_expression()?;
                if !self
                    .peek()
                    .is_some_and(|token| token.kind == TokenKind::RParen)
                {
                    return Err(self.unexpected("缺少右括号 `)`"));
                }
                self.bump();
                Ok(inner)
            }
            _ => Err(self.unexpected("此处应为表达式")),
        }
    }

    fn parse_arguments(&mut self, name: String) -> Result<Expr, ParseError> {
        let mut arguments = Vec::new();
        if self
            .peek()
            .is_some_and(|token| token.kind == TokenKind::RParen)
        {
            self.bump();
            return Ok(Expr::Call(name, arguments));
        }
        loop {
            arguments.push(self.parse_expression()?);
            match self.peek().map(|token| &token.kind) {
                Some(TokenKind::Comma) => {
                    let comma = self.bump().expect("已知存在逗号");
                    if self
                        .peek()
                        .is_some_and(|token| token.kind == TokenKind::RParen)
                    {
                        return Err(ParseError::new(
                            ParseErrorKind::UnexpectedCharacter,
                            self.peek()
                                .map(|token| token.offset)
                                .unwrap_or(comma.offset),
                            "函数参数不能为空",
                        ));
                    }
                }
                Some(TokenKind::RParen) => {
                    self.bump();
                    return Ok(Expr::Call(name, arguments));
                }
                _ => return Err(self.unexpected("缺少右括号 `)` 或参数分隔符 `,`")),
            }
        }
    }
}

/// 类型推断上下文
///
/// 变量与函数的类型全部由调用者提供, 供 [`Expression::infer_type`] 使用.
/// 未收录的变量或函数返回 `None`, 视为类型未知.
pub trait TypeContext {
    /// 变量类型, 未知时返回 `None`
    fn type_of_variable(&self, name: &str) -> Option<ValueKind>;

    /// 函数返回类型, 未知时返回 `None`
    fn type_of_function(&self, name: &str) -> Option<ValueKind>;
}

/// 空类型上下文, 不提供任何变量或函数的类型
///
/// 用于无上下文类型推断, 表达式中引用变量或调用函数时返回 `None`.
pub struct EmptyTypeContext;

impl TypeContext for EmptyTypeContext {
    fn type_of_variable(&self, _name: &str) -> Option<ValueKind> {
        None
    }

    fn type_of_function(&self, _name: &str) -> Option<ValueKind> {
        None
    }
}

/// 已解析的表达式
///
/// 解析一次后可多次求值, 适合对同一表达式使用不同上下文.
/// 默认值为字面量 `0` 的表达式.
#[derive(Debug, Clone, PartialEq)]
pub struct Expression {
    pub(crate) ast: Expr,
}

impl Default for Expression {
    /// 默认表达式为字面量 `0`
    fn default() -> Self {
        Self {
            ast: Expr::Number(Number::Integer(0)),
        }
    }
}

impl FromStr for Expression {
    type Err = ParseError;

    /// 从表达式字符串解析
    fn from_str(source: &str) -> Result<Self, Self::Err> {
        Ok(Self {
            ast: parse(source)?,
        })
    }
}

impl fmt::Display for Expression {
    /// 以紧凑的规范化格式输出 (按优先级补全括号, 不加多余空格)
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", format_expr(&self.ast))
    }
}

impl Expression {
    /// 在给定上下文中求值
    pub fn evaluate(&self, context: &dyn EvaluationContext) -> Result<Value, EvaluationError> {
        evaluate_ast(&self.ast, context, 0)
    }

    /// 推断表达式结果类型
    ///
    /// 基于语法树静态推断, 不求值. 变量与函数的类型由 [`TypeContext`] 提供,
    /// 未收录或无法确定时 (如类型不匹配) 返回 `None`.
    pub fn infer_type(&self, context: &dyn TypeContext) -> Option<ValueKind> {
        infer_expr_type(&self.ast, context)
    }

    /// 收集表达式引用的变量名
    ///
    /// 按语法树遍历顺序返回, 同一变量可能出现多次. 不含函数名.
    pub fn variables(&self) -> Vec<&str> {
        collect_names(&self.ast, NameKind::Variable)
    }

    /// 收集表达式调用的函数名
    ///
    /// 按语法树遍历顺序返回, 同一函数可能出现多次.
    pub fn functions(&self) -> Vec<&str> {
        collect_names(&self.ast, NameKind::Function)
    }

    /// 化简表达式, 返回新的简化表达式
    ///
    /// 折叠常量子表达式 (如 `2 + 3 * 4` 化简为 `14`), 消除字面量条件三元表达式的
    /// 死分支. 仅做常量折叠, 不做代数变换. 格式化输出请使用 [`Display`].
    pub fn simplify(&self) -> Expression {
        Expression {
            ast: simplify_expr(&self.ast),
        }
    }
}

/// 推断表达式子树的类型
fn infer_expr_type(expression: &Expr, context: &dyn TypeContext) -> Option<ValueKind> {
    match expression {
        Expr::Number(_) => Some(ValueKind::Number),
        Expr::Bool(_) => Some(ValueKind::Bool),
        Expr::Str(_) => Some(ValueKind::String),
        // 变量与函数的结果类型由上下文提供
        Expr::Var(name) => context.type_of_variable(name),
        Expr::Call(name, _) => context.type_of_function(name),
        Expr::Unary(operator, inner) => match operator {
            // 逻辑非按真值判断, 结果恒为布尔
            UnOp::Not => Some(ValueKind::Bool),
            UnOp::Neg | UnOp::Pos => match infer_expr_type(inner, context) {
                Some(ValueKind::Number) => Some(ValueKind::Number),
                _ => None,
            },
        },
        // 逻辑与 / 或结果恒为布尔
        Expr::Logical(..) => Some(ValueKind::Bool),
        Expr::Binary(operator, lhs, rhs) => {
            let lhs = infer_expr_type(lhs, context);
            let rhs = infer_expr_type(rhs, context);
            match operator {
                BinOp::Add => match (lhs, rhs) {
                    (Some(ValueKind::Number), Some(ValueKind::Number)) => Some(ValueKind::Number),
                    // 任一为字符串时拼接为字符串
                    (Some(ValueKind::String), Some(ValueKind::String | ValueKind::Number))
                    | (Some(ValueKind::Number), Some(ValueKind::String)) => Some(ValueKind::String),
                    _ => None,
                },
                BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem => match (lhs, rhs) {
                    (Some(ValueKind::Number), Some(ValueKind::Number)) => Some(ValueKind::Number),
                    _ => None,
                },
                // 比较运算结果恒为布尔; 两侧类型已知且不一致时必然求值失败
                BinOp::Eq | BinOp::Ne => match (lhs, rhs) {
                    (Some(lhs), Some(rhs)) if lhs == rhs => Some(ValueKind::Bool),
                    (Some(_), Some(_)) => None,
                    _ => Some(ValueKind::Bool),
                },
                BinOp::Lt | BinOp::Gt | BinOp::LtEq | BinOp::GtEq => match (lhs, rhs) {
                    (Some(ValueKind::Number), Some(ValueKind::Number))
                    | (Some(ValueKind::String), Some(ValueKind::String)) => Some(ValueKind::Bool),
                    (Some(_), Some(_)) => None,
                    _ => Some(ValueKind::Bool),
                },
            }
        }
        Expr::Ternary(_, then_branch, else_branch) => {
            match (
                infer_expr_type(then_branch, context),
                infer_expr_type(else_branch, context),
            ) {
                (Some(then_type), Some(else_type)) if then_type == else_type => Some(then_type),
                _ => None,
            }
        }
    }
}

/// 收集的名称种类
#[derive(Clone, Copy)]
enum NameKind {
    /// 变量引用 (`Expr::Var`)
    Variable,
    /// 函数调用 (`Expr::Call` 的调用名)
    Function,
}

/// 收集表达式中的变量或函数名 (按遍历顺序, 可重复)
fn collect_names(expression: &Expr, kind: NameKind) -> Vec<&str> {
    let mut names = Vec::new();
    collect_names_in(expression, kind, &mut names);
    names
}

/// 递归收集名称到指定容器
fn collect_names_in<'a>(expression: &'a Expr, kind: NameKind, out: &mut Vec<&'a str>) {
    match expression {
        Expr::Var(name) => {
            if matches!(kind, NameKind::Variable) {
                out.push(name);
            }
        }
        Expr::Call(name, arguments) => {
            if matches!(kind, NameKind::Function) {
                out.push(name);
            }
            for argument in arguments {
                collect_names_in(argument, kind, out);
            }
        }
        Expr::Unary(_, inner) => collect_names_in(inner, kind, out),
        Expr::Binary(_, lhs, rhs) => {
            collect_names_in(lhs, kind, out);
            collect_names_in(rhs, kind, out);
        }
        Expr::Logical(_, lhs, rhs) => {
            collect_names_in(lhs, kind, out);
            collect_names_in(rhs, kind, out);
        }
        Expr::Ternary(condition, then_branch, else_branch) => {
            collect_names_in(condition, kind, out);
            collect_names_in(then_branch, kind, out);
            collect_names_in(else_branch, kind, out);
        }
        Expr::Number(_) | Expr::Bool(_) | Expr::Str(_) => {}
    }
}

// -------- 化简与格式化 --------

/// 化简表达式: 递归折叠常量子表达式
///
/// 仅做常量折叠与字面量条件三元表达式的死分支消除, 不做代数变换.
fn simplify_expr(expression: &Expr) -> Expr {
    match expression {
        Expr::Unary(operator, inner) => {
            simplify_keep(Expr::Unary(*operator, Box::new(simplify_expr(inner))))
        }
        Expr::Binary(operator, lhs, rhs) => simplify_keep(Expr::Binary(
            *operator,
            Box::new(simplify_expr(lhs)),
            Box::new(simplify_expr(rhs)),
        )),
        Expr::Logical(operator, lhs, rhs) => simplify_keep(Expr::Logical(
            *operator,
            Box::new(simplify_expr(lhs)),
            Box::new(simplify_expr(rhs)),
        )),
        Expr::Ternary(condition, then_branch, else_branch) => {
            let condition = simplify_expr(condition);
            let then_branch = simplify_expr(then_branch);
            let else_branch = simplify_expr(else_branch);
            // 条件为字面量时消除死分支
            if let Some(value) = literal_value(&condition) {
                return if value.is_truthy() {
                    then_branch
                } else {
                    else_branch
                };
            }
            simplify_keep(Expr::Ternary(
                Box::new(condition),
                Box::new(then_branch),
                Box::new(else_branch),
            ))
        }
        Expr::Call(name, arguments) => {
            let arguments = arguments.iter().map(simplify_expr).collect();
            simplify_keep(Expr::Call(name.clone(), arguments))
        }
        // 字面量与变量保持原样
        _ => expression.clone(),
    }
}

/// 化简后尝试折叠为字面量
fn simplify_keep(expression: Expr) -> Expr {
    try_fold(&expression).unwrap_or(expression)
}

/// 子表达式全部为字面量时可求值折叠
///
/// 依赖求值器的短路语义: `false && a` 等无需求值变量的分支仍可折叠.
fn try_fold(expression: &Expr) -> Option<Expr> {
    evaluate_ast(expression, &EmptyEvaluationContext, 0)
        .ok()
        .map(literal_expr)
}

/// 字面量语法树转为值
fn literal_value(expression: &Expr) -> Option<Value> {
    match expression {
        Expr::Number(number) => Some(Value::Number(*number)),
        Expr::Bool(boolean) => Some(Value::Bool(*boolean)),
        Expr::Str(string) => Some(Value::String(string.clone())),
        _ => None,
    }
}

/// 求值结果转为字面量语法树
fn literal_expr(value: Value) -> Expr {
    match value {
        Value::Number(number) => Expr::Number(number),
        Value::Bool(boolean) => Expr::Bool(boolean),
        Value::String(string) => Expr::Str(string),
    }
}

/// 格式化表达式为规范化字符串
fn format_expr(expression: &Expr) -> String {
    match expression {
        Expr::Number(number) => format_number(number),
        Expr::Bool(boolean) => boolean.to_string(),
        Expr::Str(string) => format_string(string),
        Expr::Var(name) => name.clone(),
        Expr::Unary(operator, inner) => {
            let operand = format_operand(inner, PREC_UNARY, false);
            match operator {
                UnOp::Not => format!("!{operand}"),
                UnOp::Neg => format!("-{operand}"),
                UnOp::Pos => format!("+{operand}"),
            }
        }
        Expr::Binary(operator, lhs, rhs) => {
            let (precedence, operator_text) = binary_info(*operator);
            let lhs = format_operand(lhs, precedence, false);
            let rhs = format_operand(rhs, precedence, true);
            format!("{lhs}{operator_text}{rhs}")
        }
        Expr::Logical(operator, lhs, rhs) => {
            let (precedence, operator_text) = match operator {
                LogicOp::Or => (PREC_OR, "||"),
                LogicOp::And => (PREC_AND, "&&"),
            };
            let lhs = format_operand(lhs, precedence, false);
            let rhs = format_operand(rhs, precedence, true);
            format!("{lhs}{operator_text}{rhs}")
        }
        Expr::Ternary(condition, then_branch, else_branch) => {
            let condition = format_operand(condition, PREC_TERNARY, true);
            // then 分支嵌套三元时加括号便于阅读; else 分支保持右结合
            let then_branch = format_operand(then_branch, PREC_TERNARY, true);
            let else_branch = format_expr(else_branch);
            format!("{condition}?{then_branch}:{else_branch}")
        }
        Expr::Call(name, arguments) => {
            let arguments = arguments.iter().map(format_expr).collect::<Vec<_>>();
            format!("{name}({})", arguments.join(","))
        }
    }
}

/// 格式化子表达式, 优先级低于父级 (或右结合位置同级) 时加括号
fn format_operand(expression: &Expr, parent_precedence: u8, right_side: bool) -> String {
    let formatted = format_expr(expression);
    let child_precedence = precedence(expression);
    if child_precedence < parent_precedence || (right_side && child_precedence == parent_precedence)
    {
        format!("({formatted})")
    } else {
        formatted
    }
}

/// 二元运算符的优先级与文本
fn binary_info(operator: BinOp) -> (u8, &'static str) {
    match operator {
        BinOp::Add => (PREC_ADDITIVE, "+"),
        BinOp::Sub => (PREC_ADDITIVE, "-"),
        BinOp::Mul => (PREC_MULTIPLICATIVE, "*"),
        BinOp::Div => (PREC_MULTIPLICATIVE, "/"),
        BinOp::Rem => (PREC_MULTIPLICATIVE, "%"),
        BinOp::Eq => (PREC_EQUALITY, "=="),
        BinOp::Ne => (PREC_EQUALITY, "!="),
        BinOp::Lt => (PREC_ORDERING, "<"),
        BinOp::Gt => (PREC_ORDERING, ">"),
        BinOp::LtEq => (PREC_ORDERING, "<="),
        BinOp::GtEq => (PREC_ORDERING, ">="),
    }
}

/// 表达式优先级 (数值越大绑定越紧)
fn precedence(expression: &Expr) -> u8 {
    match expression {
        Expr::Ternary(..) => PREC_TERNARY,
        Expr::Logical(LogicOp::Or, ..) => PREC_OR,
        Expr::Logical(LogicOp::And, ..) => PREC_AND,
        Expr::Binary(operator, ..) => binary_info(*operator).0,
        Expr::Unary(..) => PREC_UNARY,
        _ => PREC_PRIMARY,
    }
}

const PREC_TERNARY: u8 = 1;
const PREC_OR: u8 = 2;
const PREC_AND: u8 = 3;
const PREC_EQUALITY: u8 = 4;
const PREC_ORDERING: u8 = 5;
const PREC_ADDITIVE: u8 = 6;
const PREC_MULTIPLICATIVE: u8 = 7;
const PREC_UNARY: u8 = 8;
const PREC_PRIMARY: u8 = 9;

/// 格式化数值, 浮点数保留小数形式保证往返解析类型一致
fn format_number(number: &Number) -> String {
    match number {
        Number::Integer(integer) => integer.to_string(),
        Number::Float(value) if value.fract() == 0.0 => format!("{value:.1}"),
        Number::Float(value) => value.to_string(),
    }
}

/// 格式化字符串为带引号与转义的规范形式
fn format_string(string: &str) -> String {
    let mut escaped = String::with_capacity(string.len() + 2);
    escaped.push('"');
    for character in string.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\t' => escaped.push_str("\\t"),
            '\r' => escaped.push_str("\\r"),
            character => escaped.push(character),
        }
    }
    escaped.push('"');
    escaped
}

/// 解析表达式字符串为语法树
fn parse(source: &str) -> Result<Expr, ParseError> {
    let tokens = Lexer::new(source).lex_all()?;
    if tokens.is_empty() {
        return Err(ParseError::new(ParseErrorKind::Empty, 0, "表达式不能为空"));
    }
    let mut parser = Parser {
        source,
        tokens,
        position: 0,
        depth: 0,
    };
    let expression = parser.parse_expression()?;
    if let Some(token) = parser.tokens.get(parser.position) {
        return Err(ParseError::new(
            ParseErrorKind::TrailingTokens,
            token.offset,
            "表达式末尾存在多余的符号",
        ));
    }
    Ok(expression)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse_ok(source: &str) -> Expr {
        parse(source).unwrap_or_else(|error| panic!("应成功解析 `{source}`: {error}"))
    }

    fn parse_err(source: &str) -> ParseError {
        parse(source).unwrap_err()
    }

    // -------- 字面量 --------

    #[test]
    fn number_literals() {
        assert_eq!(parse_ok("1"), Expr::Number(Number::Integer(1)));
        assert_eq!(parse_ok("1.5"), Expr::Number(Number::Float(1.5)));
        assert_eq!(parse_ok(".5"), Expr::Number(Number::Float(0.5)));
        assert_eq!(parse_ok("1."), Expr::Number(Number::Float(1.0)));
        assert_eq!(parse_ok("1e3"), Expr::Number(Number::Float(1000.0)));
        assert_eq!(parse_ok("1.5E-2"), Expr::Number(Number::Float(0.015)));
        assert_eq!(parse_ok("2e+3"), Expr::Number(Number::Float(2000.0)));
    }

    #[test]
    fn string_and_bool_literals() {
        assert_eq!(parse_ok("true"), Expr::Bool(true));
        assert_eq!(parse_ok("false"), Expr::Bool(false));
        assert_eq!(parse_ok("'abc'"), Expr::Str("abc".into()));
        assert_eq!(parse_ok("\"abc\""), Expr::Str("abc".into()));
        assert_eq!(parse_ok("'a\\'b'"), Expr::Str("a'b".into()));
        assert_eq!(parse_ok("\"a\\nb\""), Expr::Str("a\nb".into()));
        assert_eq!(parse_ok("'\\\\'"), Expr::Str("\\".into()));
    }

    #[test]
    fn words() {
        // 合法标识符 → 变量; 其余裸词 → 字符串
        assert_eq!(parse_ok("a"), Expr::Var("a".into()));
        assert_eq!(parse_ok("_a1"), Expr::Var("_a1".into()));
        assert_eq!(parse_ok("True"), Expr::Var("True".into()));
        assert_eq!(parse_ok("人物名称"), Expr::Str("人物名称".into()));
        assert_eq!(parse_ok("你好"), Expr::Str("你好".into()));
    }

    // -------- 优先级 --------

    #[test]
    fn precedence() {
        // 2 + 3 * 4
        assert_eq!(
            parse_ok("2 + 3 * 4"),
            Expr::Binary(
                BinOp::Add,
                Box::new(Expr::Number(Number::Integer(2))),
                Box::new(Expr::Binary(
                    BinOp::Mul,
                    Box::new(Expr::Number(Number::Integer(3))),
                    Box::new(Expr::Number(Number::Integer(4)))
                ))
            )
        );
        // -a * b
        assert_eq!(
            parse_ok("-a * b"),
            Expr::Binary(
                BinOp::Mul,
                Box::new(Expr::Unary(UnOp::Neg, Box::new(Expr::Var("a".into())))),
                Box::new(Expr::Var("b".into()))
            )
        );
        // 1 < 2 == true
        assert_eq!(
            parse_ok("1 < 2 == true"),
            Expr::Binary(
                BinOp::Eq,
                Box::new(Expr::Binary(
                    BinOp::Lt,
                    Box::new(Expr::Number(Number::Integer(1))),
                    Box::new(Expr::Number(Number::Integer(2)))
                )),
                Box::new(Expr::Bool(true))
            )
        );
    }

    #[test]
    fn ternary_is_right_associative() {
        assert_eq!(
            parse_ok("a ? b : c ? d : e"),
            Expr::Ternary(
                Box::new(Expr::Var("a".into())),
                Box::new(Expr::Var("b".into())),
                Box::new(Expr::Ternary(
                    Box::new(Expr::Var("c".into())),
                    Box::new(Expr::Var("d".into())),
                    Box::new(Expr::Var("e".into()))
                ))
            )
        );
    }

    #[test]
    fn function_calls() {
        assert_eq!(parse_ok("f()"), Expr::Call("f".into(), vec![]));
        assert_eq!(
            parse_ok("f(1, a + 1)"),
            Expr::Call(
                "f".into(),
                vec![
                    Expr::Number(Number::Integer(1)),
                    Expr::Binary(
                        BinOp::Add,
                        Box::new(Expr::Var("a".into())),
                        Box::new(Expr::Number(Number::Integer(1)))
                    )
                ]
            )
        );
        assert_eq!(
            parse_ok("random(5, 10, true)"),
            Expr::Call(
                "random".into(),
                vec![
                    Expr::Number(Number::Integer(5)),
                    Expr::Number(Number::Integer(10)),
                    Expr::Bool(true)
                ]
            )
        );
    }

    // -------- 不支持的特性 --------

    #[test]
    fn unsupported_syntax_errors() {
        assert_eq!(parse_err("a = 1").kind, ParseErrorKind::UnsupportedOperator);
        assert_eq!(
            parse_err("a === b").kind,
            ParseErrorKind::UnsupportedOperator
        );
        assert_eq!(
            parse_err("a !== b").kind,
            ParseErrorKind::UnsupportedOperator
        );
        assert_eq!(parse_err("a & b").kind, ParseErrorKind::UnsupportedOperator);
        assert_eq!(parse_err("a | b").kind, ParseErrorKind::UnsupportedOperator);
        assert_eq!(parse_err("$a").kind, ParseErrorKind::UnsupportedOperator);
        assert_eq!(parse_err("a.b").kind, ParseErrorKind::UnexpectedCharacter);
    }

    // -------- 结构错误 --------

    #[test]
    fn structural_errors() {
        assert_eq!(parse_err("").kind, ParseErrorKind::Empty);
        assert_eq!(parse_err("   ").kind, ParseErrorKind::Empty);
        assert_eq!(parse_err("a b").kind, ParseErrorKind::TrailingTokens);
        assert_eq!(parse_err("1 2").kind, ParseErrorKind::TrailingTokens);
        assert_eq!(parse_err("(1 + 2").kind, ParseErrorKind::UnexpectedEnd);
        assert_eq!(parse_err("a ? 1").kind, ParseErrorKind::UnexpectedEnd);
        assert_eq!(parse_err("a +").kind, ParseErrorKind::UnexpectedEnd);
        assert_eq!(parse_err("f(1,").kind, ParseErrorKind::UnexpectedEnd);
        assert_eq!(parse_err("f(1,)").kind, ParseErrorKind::UnexpectedCharacter);
        assert_eq!(parse_err("()").kind, ParseErrorKind::UnexpectedCharacter);
        assert_eq!(parse_err("a ; b").kind, ParseErrorKind::UnexpectedCharacter);
        assert_eq!(parse_err("a .").kind, ParseErrorKind::UnexpectedCharacter);
    }

    #[test]
    fn literal_errors() {
        assert_eq!(parse_err("'abc").kind, ParseErrorKind::UnclosedString);
        assert_eq!(parse_err("'a\\qb'").kind, ParseErrorKind::InvalidEscape);
        assert_eq!(parse_err("1e").kind, ParseErrorKind::InvalidNumber);
        assert_eq!(parse_err("1e+").kind, ParseErrorKind::InvalidNumber);
        assert_eq!(parse_err("1x").kind, ParseErrorKind::InvalidNumber);
        assert_eq!(parse_err("0x10").kind, ParseErrorKind::InvalidNumber);
        assert_eq!(parse_err("1.5abc").kind, ParseErrorKind::InvalidNumber);
    }

    #[test]
    fn nesting_too_deep() {
        let source = format!("{}1{}", "(".repeat(300), ")".repeat(300));
        assert_eq!(parse_err(&source).kind, ParseErrorKind::NestingTooDeep);
    }

    #[test]
    fn error_offset_points_into_source() {
        let error = parse_err("a + ;");
        assert_eq!(error.offset, 4);
        assert_eq!(error.message, "无法识别的字符 `;`");
    }

    // -------- 化简与格式化 --------

    fn simplify(source: &str) -> String {
        Expression {
            ast: parse(source).unwrap(),
        }
        .simplify()
        .to_string()
    }

    #[test]
    fn simplify_constant_folding() {
        assert_eq!(simplify("2 + 3 * 4"), "14");
        assert_eq!(simplify("(1 + 2) * 3"), "9");
        assert_eq!(simplify("(1 + 2) * (3 + 4)"), "21");
        assert_eq!(simplify("10 / 4"), "2.5");
        assert_eq!(simplify("1.0 + 2"), "3.0");
        assert_eq!(simplify("!true"), "false");
        assert_eq!(simplify("true && false"), "false");
        assert_eq!(simplify("1 + \"x\""), "\"1x\"");
        assert_eq!(simplify("'x' + \"y\""), "\"xy\"");
    }

    #[test]
    fn simplify_short_circuit() {
        // 短路分支中的变量不会被求值, 可安全折叠
        assert_eq!(simplify("false && a"), "false");
        assert_eq!(simplify("true || a"), "true");
        // 需要求值变量的情况不折叠
        assert_eq!(simplify("a || false"), "a||false");
        assert_eq!(simplify("true && a"), "true&&a");
    }

    #[test]
    fn simplify_ternary_dead_branch() {
        assert_eq!(simplify("1 > 0 ? \"高\" : \"低\""), "\"高\"");
        assert_eq!(simplify("true ? false : a"), "false");
        assert_eq!(simplify("0 ? a : b"), "b");
        // 条件不恒定保持原样
        assert_eq!(simplify("hp > 0 ? 1 : 2"), "hp>0?1:2");
    }

    #[test]
    fn simplify_keeps_variables_and_errors() {
        assert_eq!(simplify("a + 1"), "a+1");
        assert_eq!(simplify("1 / 0"), "1/0"); // 除零不折叠
        assert_eq!(simplify("random(1 + 2, 3)"), "random(3,3)"); // 参数折叠, 调用保留
        assert_eq!(simplify("人物名称"), "\"人物名称\"");
    }

    #[test]
    fn format_preserves_precedence() {
        assert_eq!(simplify("a - (b - c)"), "a-(b-c)");
        assert_eq!(simplify("(a + b) * c"), "(a+b)*c");
        assert_eq!(simplify("-(a + b)"), "-(a+b)");
        assert_eq!(simplify("!a > 1"), "!a>1");
        assert_eq!(simplify("a && (b || c)"), "a&&(b||c)");
        assert_eq!(simplify("a ? b : c ? d : e"), "a?b:c?d:e");
        assert_eq!(simplify("(a ? b : c) + 1"), "(a?b:c)+1");
        assert_eq!(simplify("--a"), "--a");
    }

    #[test]
    fn format_round_trip() {
        // 格式化结果重新解析后语法树一致
        let sources = [
            "a + b",
            "a - (b - c)",
            "(a + b) * c",
            "a && (b || c)",
            "a ? b : c ? d : e",
            "-(a + b)",
            "!a > 1",
            "f(1, a + b)",
            "5.0",
            "1 + 2 == 3",
            "a < b <= c",
        ];
        for source in sources {
            let expression = parse(source).unwrap();
            let formatted = format_expr(&expression);
            assert_eq!(
                parse(&formatted).unwrap(),
                expression,
                "往返解析不一致: {source} -> {formatted}"
            );
        }
    }

    #[test]
    fn format_number_representation() {
        assert_eq!(format_expr(&Expr::Number(Number::Integer(5))), "5");
        assert_eq!(format_expr(&Expr::Number(Number::Float(5.0))), "5.0");
        assert_eq!(format_expr(&Expr::Number(Number::Float(2.5))), "2.5");
    }

    // -------- 表达式属性 --------

    #[test]
    fn expression_partial_eq() {
        let a = Expression {
            ast: parse("1 + 2").unwrap(),
        };
        let b = Expression {
            ast: parse("1 + 2").unwrap(),
        };
        let c = Expression {
            ast: parse("1 + 3").unwrap(),
        };
        assert_eq!(a, b);
        assert_ne!(a, c);
    }

    #[test]
    fn expression_default() {
        let expression = Expression::default();
        assert_eq!(expression.simplify().to_string(), "0");
        assert_eq!(
            expression
                .simplify()
                .evaluate(&EmptyEvaluationContext)
                .unwrap(),
            Value::from(0)
        );
        assert_eq!(
            expression.evaluate(&EmptyEvaluationContext).unwrap(),
            Value::from(0)
        );
    }
}
